from rdkit import Chem
for tag in [Chem.ChiralType.CHI_TETRAHEDRAL_CW,Chem.ChiralType.CHI_TETRAHEDRAL_CCW]:
 rw=Chem.RWMol()
 for e in ['C','C','C','O','C','C','C','C','C','C','C']:rw.AddAtom(Chem.Atom(e))
 edges=[(0,2,Chem.BondType.SINGLE),(2,1,Chem.BondType.SINGLE),(2,3,Chem.BondType.DOUBLE),(0,4,Chem.BondType.SINGLE),(4,5,Chem.BondType.SINGLE),(5,6,Chem.BondType.SINGLE),(6,7,Chem.BondType.SINGLE),(7,1,Chem.BondType.SINGLE),(0,8,Chem.BondType.SINGLE),(8,9,Chem.BondType.SINGLE),(9,10,Chem.BondType.SINGLE),(10,1,Chem.BondType.SINGLE)]
 for i,j,b in edges:rw.AddBond(i,j,b)
 m=rw.GetMol(); Chem.SanitizeMol(m); m.GetAtomWithIdx(0).SetChiralTag(tag); m=Chem.AddHs(m); Chem.AssignStereochemistry(m,cleanIt=True,force=True)
 print(tag,m.GetAtomWithIdx(0).GetProp('_CIPCode'),[(x.GetIdx(),x.GetSymbol()) for x in m.GetAtomWithIdx(0).GetNeighbors()])
